export const GE_ONLYMAP_DEMO_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>OnlyMap on GeoEngine demo<\/title>\n<link rel=\"stylesheet\" href=\"https://unpkg.com/@nika-js/onlymap@0.12.1/dist/onlymapjs.css\">\n<link href=\"https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--bg:#170d19;--panel:rgba(31,20,34,.94);--line:#3a2b3e;--text:#ece6ee;--muted:#a99fae;--accent:#c5ff5a;--ink:#1b2400;--amber:#eba941;--bad:#e66767;--mono:\"JetBrains Mono\",ui-monospace,Menlo,monospace}\n*{box-sizing:border-box}\nhtml,body{margin:0;height:100%;background:var(--bg);color:var(--text);font:14px/1.45 \"Space Grotesk\",system-ui,sans-serif}\n.stage{position:relative;height:100%;min-height:520px}\nom-map{display:block;position:absolute;inset:0}\n.panel{position:absolute;top:12px;left:12px;width:300px;max-width:calc(100% - 24px);background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:14px 16px;z-index:5;backdrop-filter:blur(6px)}\n.panel h3{margin:0 0 2px;font-size:15px}\n.panel .sub{color:var(--muted);font-size:12px;margin-bottom:10px}\nlabel{display:block;font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin:10px 0 4px;font-weight:600}\nselect,button{width:100%;font:inherit;border-radius:9px;border:1px solid var(--line);background:#271a2b;color:var(--text);padding:7px 9px}\nbutton.run{margin-top:12px;background:var(--accent);color:var(--ink);border:none;font-weight:700;cursor:pointer;padding:9px}\nbutton.run:disabled{opacity:.55;cursor:default}\n.meta{display:grid;grid-template-columns:auto 1fr;gap:3px 10px;font-size:12.5px;margin-top:12px}\n.meta span{color:var(--muted)}\n.meta b{font-weight:600;text-align:right;font-family:var(--mono);font-size:12px}\n.pill{display:inline-block;border-radius:999px;padding:0 9px;font:600 11px var(--mono);background:#3a2b3e}\n.pill.running{background:var(--amber);color:#1b1200}.pill.completed{background:var(--accent);color:var(--ink)}.pill.blocked{background:var(--bad);color:#200}\n.bar{height:6px;background:#3a2b3e;border-radius:4px;margin-top:10px;overflow:hidden}\n.bar i{display:block;height:100%;width:0;background:var(--accent);transition:width .4s}\n.restricted{color:var(--amber);font-size:12px;margin-top:6px;display:none}\n.restricted.on{display:block}\n.log{position:absolute;right:12px;bottom:66px;width:380px;max-width:calc(100% - 24px);max-height:118px;overflow:auto;background:rgba(18,10,20,.92);border:1px solid var(--line);border-radius:12px;padding:8px 10px;font:11.5px/1.5 var(--mono);color:#cfc6d2;z-index:5}\n.log div{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.log .m{color:var(--accent)}.log .s{color:var(--muted)}.log .e{color:var(--bad)}\n.legend{position:absolute;right:12px;top:12px;background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:10px 12px;font-size:12px;z-index:5;min-width:170px}\n.legend .ramp{height:10px;border-radius:3px;margin:6px 0 2px}\n.legend .ends{display:flex;justify-content:space-between;color:var(--muted);font-size:11px}\n.legend .k{display:flex;align-items:center;gap:7px;margin-top:5px;color:var(--muted)}\n.legend .k i{width:12px;height:12px;border-radius:3px;display:inline-block}\n.tip{background:#120a14;color:#ece6ee;border:1px solid #3a2b3e;border-radius:8px;padding:7px 10px;font:12px \"Space Grotesk\",system-ui,sans-serif;line-height:1.5}\n.tip b{color:#c5ff5a}\n@media (max-width:640px){.log{display:none}.legend{display:none}}\n@media (max-width:560px){\n  .panel{top:8px;left:8px;right:8px;width:auto;max-width:none;padding:10px 12px}\n  .panel h3{font-size:14px}.panel .sub,.opt{display:none}\n  .pick{display:grid;grid-template-columns:1fr 1fr;gap:8px}\n  label{margin:4px 0 3px}\n  select{padding:6px 7px;font-size:13px}\n  button.run{margin-top:8px;padding:8px}\n  .meta{grid-template-columns:auto 1fr auto 1fr auto 1fr;gap:2px 6px;margin-top:8px;font-size:11.5px}\n  .bar{margin-top:6px}\n}\n<\/style>\n<\/head>\n<body>\n<div class=\"stage\">\n  <om-map id=\"map\" center=\"[5.36, 52.53]\" zoom=\"9.1\" basemap=\"satellite\">\n    <om-fallback><p style=\"padding:20px\">This interactive map needs JavaScript and WebGL.<\/p><\/om-fallback>\n    <om-layer id=\"aoi\" type=\"GeoJsonLayer\"\n      filled=\"false\" stroked=\"true\" get-line-color=\"[197,255,90,230]\" line-width-min-pixels=\"2\"\n      dash=\"[6, 4]\" label=\"Area of interest\"><\/om-layer>\n    <om-layer id=\"tasks\" type=\"GeoJsonLayer\" refresh=\"1s\"\n      filled=\"true\" stroked=\"true\" get-fill-color=\"$fill\" get-line-color=\"$line\" line-width-min-pixels=\"1\"\n      pickable label=\"Tasks\"><\/om-layer>\n    <om-behavior on=\"hover\" layer=\"tasks\" action=\"show-tooltip\" template=\"#task-tip\"><\/om-behavior>\n  <\/om-map>\n\n  <div class=\"panel\">\n    <h3>Run a batch job from the map<\/h3>\n    <div class=\"sub\">Each square on the map is one task in the batch job.<\/div>\n    <div class=\"pick\">\n      <div><label for=\"scn\">Scenario<\/label><select id=\"scn\"><\/select><\/div>\n      <div><label for=\"role\">Signed in as<\/label><select id=\"role\"><option value=\"analyst\">Analyst<\/option><option value=\"cleared\">Cleared analyst<\/option><\/select><\/div>\n    <\/div>\n    <div class=\"restricted\" id=\"rnote\">This worker is restricted. Only cleared roles can run it.<\/div>\n    <button class=\"run\" id=\"run\" type=\"button\">Run batch job<\/button>\n    <div class=\"meta\" id=\"meta\">\n      <span class=\"opt\">Worker<\/span><b class=\"opt\" id=\"m-worker\">\u2014<\/b>\n      <span class=\"opt\">Machine class<\/span><b class=\"opt\" id=\"m-class\">\u2014<\/b>\n      <span class=\"opt\">Job<\/span><b class=\"opt\" id=\"m-job\">\u2014<\/b>\n      <span>Status<\/span><b><span class=\"pill\" id=\"m-status\">idle<\/span><\/b>\n      <span>Tasks<\/span><b id=\"m-tasks\">\u2014<\/b>\n      <span>Pods running<\/span><b id=\"m-pods\">\u2014<\/b>\n      <span class=\"opt\">Elapsed<\/span><b class=\"opt\" id=\"m-time\">\u2014<\/b>\n    <\/div>\n    <div class=\"bar\"><i id=\"m-bar\"><\/i><\/div>\n  <\/div>\n\n  <div class=\"legend\" id=\"legend\"><\/div>\n  <div class=\"log\" id=\"log\" aria-live=\"polite\"><\/div>\n<\/div>\n\n<template id=\"task-tip\">\n  <div class=\"tip\"><b>{{task}}<\/b> \u00b7 {{state}}<br>{{scene}}<br>{{detail}}<\/div>\n<\/template>\n\n<script type=\"module\">\nimport { OmMap } from \"https://unpkg.com/@nika-js/onlymap@0.12.1\";\n\nconst HOST = \"https://geoengine.demo\";\n// Demo time: 1 second on screen stands for 90 seconds of processing.\nconst SCALE = 90;\n\nconst SCENARIOS = [\n  { id: 0, name: \"Cloud-free NDVI \u00b7 crop monitoring\", center: [5.36, 52.53], zoom: 9.1,\n    bbox: [5.30, 52.40, 5.82, 52.64], cols: 8, rows: 5,\n    worker: \"cloud-removal-ndvi\", version: \"2.3.1\", cls: \"highmem\", pool: 12, restricted: false,\n    metric: \"mean NDVI\", ramp: [[226, 244, 199], [26, 110, 38]], domain: [0.15, 0.85], fmt: v => v.toFixed(2),\n    gen: (cx, cy, r) => 0.35 + 0.4 * r() + 0.1 * Math.sin(cx * 9) },\n  { id: 1, name: \"Flood extent from radar \u00b7 disaster response\", center: [105.53, 10.09], zoom: 9.1,\n    bbox: [105.48, 9.94, 105.98, 10.22], cols: 8, rows: 5,\n    worker: \"sar-flood-extent\", version: \"1.4.0\", cls: \"cpu\", pool: 16, restricted: false,\n    metric: \"area flooded\", ramp: [[222, 235, 247], [8, 69, 148]], domain: [0, 80], fmt: v => v.toFixed(0) + \"%\",\n    gen: (cx, cy, r) => Math.max(0, Math.min(80, 70 - Math.abs(cy - 10.06) * 600 + 25 * r())) },\n  { id: 2, name: \"New-building detection \u00b7 restricted\", center: [3.97, 51.97], zoom: 9.9,\n    bbox: [3.96, 51.90, 4.26, 52.03], cols: 7, rows: 4,\n    worker: \"building-change-detect\", version: \"3.0.2\", cls: \"gpu\", pool: 6, restricted: true,\n    metric: \"new buildings\", ramp: [[254, 230, 206], [166, 54, 3]], domain: [0, 40], fmt: v => v.toFixed(0),\n    gen: (cx, cy, r) => Math.round(40 * Math.pow(r(), 2)) },\n];\n\n// ---------------------------------------------------------------- simulated API\nlet rngSeed = 7;\nconst rand = () => ((rngSeed = (rngSeed * 16807) % 2147483647) / 2147483647);\nlet job = null;\nconst $ = id => document.getElementById(id);\nconst log = (cls, msg) => {\n  const d = document.createElement(\"div\"); d.className = cls; d.textContent = msg;\n  $(\"log\").appendChild(d); $(\"log\").scrollTop = 1e9;\n};\nconst lerp = (a, b, t) => a.map((v, i) => Math.round(v + (b[i] - v) * t));\nconst fmtDur = s => s < 60 ? `${Math.round(s)} s` : `${Math.floor(s / 60)} min ${String(Math.round(s % 60)).padStart(2, \"0\")} s`;\n\nfunction grid(s) {\n  const [w, so, e, n] = s.bbox, dx = (e - w) / s.cols, dy = (n - so) / s.rows, cells = [];\n  for (let r = 0; r < s.rows; r++) for (let c = 0; c < s.cols; c++) {\n    const x0 = w + c * dx, y0 = so + r * dy;\n    cells.push({ ring: [[x0, y0], [x0 + dx, y0], [x0 + dx, y0 + dy], [x0, y0 + dy], [x0, y0]], cx: x0 + dx / 2, cy: y0 + dy / 2 });\n  }\n  return cells;\n}\n\nfunction aoi(s) {\n  const [w, so, e, n] = s.bbox;\n  return { type: \"FeatureCollection\", features: [{ type: \"Feature\", properties: {},\n    geometry: { type: \"Polygon\", coordinates: [[[w, so], [e, so], [e, n], [w, n], [w, so]]] } }] };\n}\n\nfunction startJob(s) {\n  rngSeed = 11 + s.id * 101;\n  const cells = grid(s);\n  const tasks = cells.map((g, i) => ({\n    i, g, dur: 1.6 + rand() * 3.2, value: s.gen(g.cx, g.cy, rand),\n    mem: s.cls === \"highmem\" ? 28 + rand() * 14 : s.cls === \"gpu\" ? 9 + rand() * 5 : 3 + rand() * 3,\n    start: null, end: null,\n  }));\n  const id = \"j-\" + Math.random().toString(36).slice(2, 8) + Math.random().toString(36).slice(2, 6);\n  job = { id, s, tasks, t0: performance.now(), done: false };\n  return job;\n}\n\nfunction tick() {\n  if (!job) return;\n  const now = (performance.now() - job.t0) / 1000;\n  let running = 0;\n  for (const t of job.tasks) if (t.start !== null && t.end > now) running++;\n  for (const t of job.tasks) {\n    if (t.start === null && running < job.s.pool && now > 0.6) { t.start = now; t.end = now + t.dur; running++; }\n  }\n}\n\nfunction snapshot() {\n  tick();\n  const now = (performance.now() - job.t0) / 1000, s = job.s;\n  let done = 0, run = 0;\n  const features = job.tasks.map(t => {\n    let state = \"queued\", fill = [255, 255, 255, 28], line = [255, 255, 255, 90], detail = \"waiting for a free pod\";\n    if (t.start !== null && now < t.end) {\n      state = \"running\"; run++;\n      const pulse = 0.5 + 0.5 * Math.sin(now * 5 + t.i);\n      fill = [235, 169, 65, Math.round(70 + 90 * pulse)]; line = [235, 169, 65, 255];\n      detail = `running ${fmtDur((now - t.start) * SCALE)} \u00b7 ${s.cls} pool`;\n    } else if (t.start !== null) {\n      state = \"completed\"; done++;\n      const k = Math.max(0, Math.min(1, (t.value - s.domain[0]) / (s.domain[1] - s.domain[0])));\n      fill = [...lerp(s.ramp[0], s.ramp[1], k), 215]; line = [255, 255, 255, 140];\n      detail = `${s.metric} ${s.fmt(t.value)} \u00b7 ran ${fmtDur(t.dur * SCALE)} \u00b7 peak RAM ${t.mem.toFixed(1)} GiB`;\n    }\n    return { type: \"Feature\", properties: { task: `task ${String(t.i + 1).padStart(3, \"0\")}`, state, fill, line, detail,\n      scene: `scene ${s.worker.split(\"-\")[0]}_${String(t.i + 1).padStart(3, \"0\")}.tif` },\n      geometry: { type: \"Polygon\", coordinates: [t.g.ring] } };\n  });\n  const total = job.tasks.length;\n  if (done === total && !job.done) {\n    job.done = true;\n    log(\"m\", `job ${job.id} completed \u00b7 ${total} results in shared storage`);\n  }\n  updatePanel(done, run, total, now);\n  return { type: \"FeatureCollection\", features };\n}\n\nlet lastLogged = -1;\nasync function fakeFetch(url, init) {\n  const u = String(url);\n  if (!u.startsWith(HOST)) return fetch(url, init);\n  const json = body => new Response(JSON.stringify(body), { status: 200, headers: { \"content-type\": \"application/geo+json\" } });\n  let m = u.match(/\\/v1\\/aoi\\/(\\d+)\\.geojson/);\n  if (m) return json(aoi(SCENARIOS[+m[1]]));\n  m = u.match(/\\/v1\\/jobs\\/([^/]+)\\/tasks\\.geojson/);\n  if (m && job && m[1] === job.id) {\n    const fc = snapshot();\n    const done = fc.features.filter(f => f.properties.state === \"completed\").length;\n    if (!job.done && done !== lastLogged) { lastLogged = done; log(\"s\", `GET /v1/jobs/${job.id}/tasks.geojson \u2192 200 \u00b7 ${done}/${fc.features.length} done`); }\n    return json(fc);\n  }\n  return json({ type: \"FeatureCollection\", features: [] });\n}\nOmMap.configureData({ fetch: fakeFetch });\n\n// ---------------------------------------------------------------- UI\nconst map = $(\"map\"), tasksEl = map.querySelector(\"#tasks\"), aoiEl = map.querySelector(\"#aoi\");\nSCENARIOS.forEach(s => $(\"scn\").insertAdjacentHTML(\"beforeend\", `<option value=\"${s.id}\">${s.name}<\/option>`));\n\nfunction current() { return SCENARIOS[+$(\"scn\").value]; }\nfunction legend(s) {\n  const a = `rgb(${s.ramp[0]})`, b = `rgb(${s.ramp[1]})`;\n  $(\"legend\").innerHTML = `<b>${s.metric[0].toUpperCase() + s.metric.slice(1)}<\/b> per task\n    <div class=\"ramp\" style=\"background:linear-gradient(90deg,${a},${b})\"><\/div>\n    <div class=\"ends\"><span>${s.fmt(s.domain[0])}<\/span><span>${s.fmt(s.domain[1])}<\/span><\/div>\n    <div class=\"k\"><i style=\"background:rgba(235,169,65,.8)\"><\/i>running<\/div>\n    <div class=\"k\"><i style=\"background:rgba(255,255,255,.18);border:1px solid rgba(255,255,255,.5)\"><\/i>queued<\/div>`;\n}\nfunction setStatus(st) { const p = $(\"m-status\"); p.textContent = st; p.className = \"pill \" + st; }\nfunction updatePanel(done, run, total, now) {\n  $(\"m-tasks\").textContent = `${done} / ${total} done`;\n  $(\"m-pods\").textContent = String(run);\n  $(\"m-time\").textContent = fmtDur(now * SCALE);\n  $(\"m-bar\").style.width = (100 * done / total) + \"%\";\n  setStatus(done === total ? \"completed\" : run ? \"running\" : \"queued\");\n  if (done === total) $(\"run\").disabled = false;\n}\nfunction selectScenario() {\n  const s = current();\n  job = null;\n  $(\"m-worker\").textContent = `${s.worker} ${s.version}`;\n  $(\"m-class\").textContent = s.cls;\n  [\"m-job\", \"m-tasks\", \"m-pods\", \"m-time\"].forEach(k => $(k).textContent = \"\u2014\");\n  $(\"m-bar\").style.width = \"0\"; setStatus(\"idle\");\n  $(\"rnote\").classList.toggle(\"on\", s.restricted);\n  $(\"run\").disabled = false;\n  aoiEl.setAttribute(\"data\", `${HOST}/v1/aoi/${s.id}.geojson`);\n  tasksEl.setAttribute(\"data\", `${HOST}/v1/jobs/none-${s.id}/tasks.geojson`);\n  legend(s);\n  // On a phone the panel sits on top, so frame the area of interest lower and a little wider.\n  const narrow = window.innerWidth < 560, [w, so, e, n] = s.bbox;\n  const center = narrow ? [(w + e) / 2, (so + n) / 2 + (n - so) * 0.55] : s.center;\n  Promise.resolve(map.ready).then(() => map.flyTo(center, narrow ? s.zoom - 0.9 : s.zoom));\n}\n$(\"scn\").addEventListener(\"change\", selectScenario);\n\n$(\"run\").addEventListener(\"click\", () => {\n  const s = current(), role = $(\"role\").value;\n  const body = { worker: s.worker, version: s.version, machine_class: s.cls, items: s.cols * s.rows };\n  log(\"m\", `POST /v1/jobs ${JSON.stringify(body)}`);\n  if (s.restricted && role !== \"cleared\") {\n    log(\"e\", `403 Forbidden \u00b7 role \"analyst\" is not granted ${s.worker} \u00b7 no pod created`);\n    $(\"m-job\").textContent = \"\u2014\"; setStatus(\"blocked\");\n    return;\n  }\n  const j = startJob(s); lastLogged = -1;\n  log(\"s\", `202 Accepted {\"job_id\":\"${j.id}\",\"status\":\"queued\",\"tasks\":${j.tasks.length}}`);\n  $(\"m-job\").textContent = j.id;\n  $(\"run\").disabled = true;\n  tasksEl.setAttribute(\"data\", `${HOST}/v1/jobs/${j.id}/tasks.geojson`);\n});\n\nselectScenario();\nlog(\"s\", \"Demo: API responses are simulated in this page.\");\n<\/script>\n<\/body>\n<\/html>\n";
